resource "google_storage_bucket_object" "index" {
  name          = "index.yaml"
  source        = "${path.module}/template/index.yaml"
  bucket        = module.storage.bucket
  cache_control = "no-cache, max-age=0"
}

module "helm" {
  source      = "JamesWoolfenden/helm/gcp"
  binding     = var.binding
  bucket_name = var.bucket_name
}

variable "binding" {
  description = "Permissions to set on the bucket"
  type = object({
    binding_members = list(string)
    binding_role    = string
  })
  validation {
    condition     = length(keys(var.binding)) > 0
    error_message = "binding must contain at least one permission entry."
  }
}

# holden:ignore:HLD_TF_004 — this repo is consumed only as a child module (see example/examplea), backend belongs to the caller
terraform {
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "7.42.0"
    }
  }
  required_version = ">= 1.5.0"
}
